package com.nthexperience.desktop;

import android.content.Context;
import android.net.Uri;
import android.provider.DocumentsContract;
import java.io.*;
import java.util.*;
import java.util.zip.*;

/** ZIP operations always create new output. Originals are never removed or overwritten. */
final class XpZip {
    static final int ENTRIES=2000,DEPTH=16;static final long BYTES=128L*1024*1024;
    interface Source{InputStream open()throws IOException;}
    static final class Entry {final String path;final boolean directory;Entry(String path,boolean directory){this.path=path;this.directory=directory;}}
    static String path(String raw)throws IOException{String name=raw.replace('\\','/');if(name.startsWith("/")||name.indexOf(':')>=0||name.length()>1024)throw new IOException("Unsafe archive path");while(name.endsWith("/"))name=name.substring(0,name.length()-1);String[] parts=name.split("/",-1);if(parts.length>DEPTH)throw new IOException("Archive nesting limit");for(String part:parts)try{if(!part.equals(DocumentOps.name(part)))throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw new IOException("Unsafe archive path");}return String.join("/",parts);}
    static List<Entry> inspect(Source source,DocumentOps.Cancel cancel)throws IOException{List<Entry> entries=new ArrayList<>();Map<String,Boolean> paths=new HashMap<>();long total=0;try(ZipInputStream zip=new ZipInputStream(new Bounded(source.open()))){ZipEntry entry;byte[] block=new byte[16384];while((entry=zip.getNextEntry())!=null){cancel.check();if(entries.size()>=ENTRIES)throw new IOException("Archive entry limit");String name=path(entry.getName()),key=name.toLowerCase(Locale.ROOT);String[] pieces=key.split("/");String parent="";for(int i=0;i<pieces.length-1;i++){parent+=pieces[i]+"/";String p=parent.substring(0,parent.length()-1);if(Boolean.FALSE.equals(paths.get(p)))throw new IOException("Conflicting archive paths");paths.put(p,true);}boolean directory=entry.isDirectory()||entry.getName().endsWith("\\");if(paths.containsKey(key)&&(!directory||!paths.get(key)))throw new IOException("Duplicate archive path");paths.put(key,directory);entries.add(new Entry(name,directory));int n;while((n=zip.read(block))!=-1){cancel.check();total+=n;if(total>BYTES)throw new IOException("Archive expands beyond 128 MB");}zip.closeEntry();}}if(entries.isEmpty())throw new IOException("Archive is empty or unsupported");return entries;}
    static String compress(Context c,List<DocumentOps.Ref> sources,Uri parent,String requested,DocumentOps.Cancel cancel)throws Exception{
        if(sources.isEmpty())throw new IOException("Select files or folders first");String clean=DocumentOps.name(requested);if(!clean.toLowerCase(Locale.ROOT).endsWith(".zip"))clean+=".zip";clean=DocumentOps.available(c,parent,clean,true,cancel);Uri target=DocumentsContract.createDocument(c.getContentResolver(),parent,"application/zip",clean);if(target==null)throw new IOException("Could not create ZIP");boolean complete=false;long[] total={0};int[] count={0};Set<String> names=new HashSet<>(),visited=new HashSet<>();try(OutputStream out=c.getContentResolver().openOutputStream(target,"w")){if(out==null)throw new IOException("ZIP location unavailable");try(ZipOutputStream zip=new ZipOutputStream(out)){for(DocumentOps.Ref source:sources)write(c,source,"",zip,cancel,total,count,names,visited,0);}complete=true;}finally{if(!complete)try{DocumentsContract.deleteDocument(c.getContentResolver(),target);}catch(Exception ignored){}}
        return "Created "+clean+" • "+count[0]+" archive entries";
    }
    private static void write(Context c,DocumentOps.Ref ref,String prefix,ZipOutputStream zip,DocumentOps.Cancel cancel,long[] total,int[] count,Set<String> names,Set<String> visited,int depth)throws Exception{
        cancel.check();if(depth>DEPTH||++count[0]>ENTRIES)throw new IOException("ZIP supports 2,000 entries and 16 nested levels");String name=path(prefix+ref.item.name);if(!names.add(name.toLowerCase(Locale.ROOT)))throw new IOException("Duplicate ZIP name");String identity=ref.uri.getAuthority()+":"+DocumentsContract.getDocumentId(ref.uri);if(!visited.add(identity))throw new IOException("Repeated or circular folder reference");zip.putNextEntry(new ZipEntry(name+(ref.item.directory()?"/":"")));
        if(ref.item.directory()){zip.closeEntry();for(DocumentOps.Ref child:DocumentOps.children(c,ref.uri,cancel,true))write(c,child,name+"/",zip,cancel,total,count,names,visited,depth+1);}else{try(InputStream in=c.getContentResolver().openInputStream(ref.uri)){if(in==null)throw new IOException("File unavailable");byte[] bytes=new byte[16384];int n;while((n=in.read(bytes))!=-1){cancel.check();total[0]+=n;if(total[0]>BYTES)throw new IOException("ZIP input limit is 128 MB");zip.write(bytes,0,n);}}zip.closeEntry();}
    }
    static String extract(Context c,DocumentOps.Ref source,Uri parent,DocumentOps.Cancel cancel)throws Exception{
        Source input=()->c.getContentResolver().openInputStream(source.uri);List<Entry> entries=inspect(input,cancel);String stem=source.item.name.replaceFirst("(?i)\\.zip$","");if(stem.length()>180)stem=stem.substring(0,180);String name=DocumentOps.available(c,parent,stem+" extracted",true,cancel);Uri root=DocumentOps.createFolder(c,parent,name,cancel);Map<String,Uri> folders=new HashMap<>();folders.put("",root);boolean complete=false;long total=0;int count=0;
        try(ZipInputStream zip=new ZipInputStream(new Bounded(input.open()))){ZipEntry raw;byte[] bytes=new byte[16384];while((raw=zip.getNextEntry())!=null){cancel.check();if(count>=entries.size())throw new IOException("Archive changed during extraction");Entry expected=entries.get(count++);String path=path(raw.getName());if(!expected.path.equals(path)||expected.directory!=(raw.isDirectory()||raw.getName().endsWith("\\")))throw new IOException("Archive changed during extraction");String[] parts=path.split("/");String prefix="";Uri folder=root;for(int i=0;i<parts.length-(expected.directory?0:1);i++){prefix+=parts[i]+"/";Uri existing=folders.get(prefix);if(existing==null){existing=DocumentsContract.createDocument(c.getContentResolver(),folder,DocumentsContract.Document.MIME_TYPE_DIR,parts[i]);if(existing==null)throw new IOException("Could not create archive folder");folders.put(prefix,existing);}folder=existing;}
            if(!expected.directory){String leaf=parts[parts.length-1];Uri file=DocumentsContract.createDocument(c.getContentResolver(),folder,FileLaunch.mime(leaf,"application/octet-stream"),leaf);if(file==null)throw new IOException("Could not create extracted file");try(OutputStream out=c.getContentResolver().openOutputStream(file,"w")){if(out==null)throw new IOException("Extracted file is not writable");int n;while((n=zip.read(bytes))!=-1){cancel.check();total+=n;if(total>BYTES)throw new IOException("Extraction limit exceeded");out.write(bytes,0,n);}}}else{int n;while((n=zip.read(bytes))!=-1){cancel.check();total+=n;if(total>BYTES)throw new IOException("Extraction limit exceeded");}}zip.closeEntry();}if(count!=entries.size())throw new IOException("Archive changed during extraction");complete=true;
        }finally{if(!complete)try{DocumentsContract.deleteDocument(c.getContentResolver(),root);}catch(Exception ignored){}}
        return "Extracted "+count+" entries into "+name;
    }
    private static final class Bounded extends FilterInputStream {long read;Bounded(InputStream in)throws IOException{super(in);if(in==null)throw new IOException("Archive unavailable");}private void add(int n)throws IOException{if(n>0&&(read+=n)>BYTES)throw new IOException("Compressed ZIP is too large");}@Override public int read()throws IOException{int n=super.read();if(n>=0)add(1);return n;}@Override public int read(byte[] b,int o,int n)throws IOException{int value=in.read(b,o,n);add(value);return value;}}
    private XpZip(){}
}
